          if (raw.includes("under") || raw.includes("review") || raw.includes("pending")) return { label: "Under review", className: "is-review" };
          if (raw.includes("offline") || raw.includes("closed") || raw.includes("pause")) return { label: "Offline", className: "is-offline" };
