        function enhanceDropdown(select) {
          if (!select || select.dataset.emyEnhanced === "true") return;
          const control = select.closest(".control");
          if (!control) return;
          select.dataset.emyEnhanced = "true";
          select.classList.add("native-select-hidden");
          select.tabIndex = -1;

          const wrapper = document.createElement("div");
          wrapper.className = "custom-select-wrap";
          const button = document.createElement("button");
          button.type = "button";
          button.className = "custom-select";
          button.setAttribute("aria-haspopup", "listbox");
          button.setAttribute("aria-expanded", "false");
          const value = document.createElement("span");
          value.className = "custom-select-value";
          const chevron = document.createElement("i");
          chevron.className = "select-chevron";
          chevron.setAttribute("aria-hidden", "true");
          const menu = document.createElement("div");
          menu.className = "custom-select-menu";
          menu.setAttribute("role", "listbox");
          button.appendChild(value);
          button.appendChild(chevron);
          wrapper.appendChild(button);
          wrapper.appendChild(menu);
          control.appendChild(wrapper);
          select.__customButton = button;

          const close = () => {
            wrapper.classList.remove("is-open");
            button.setAttribute("aria-expanded", "false");
          };
          const update = () => {
            const selected = select.options[select.selectedIndex] || select.options[0];
            value.textContent = selected ? selected.textContent : "";
            select.classList.toggle("has-value", !!select.value);
            button.classList.toggle("is-empty", !select.value);
            menu.querySelectorAll(".custom-select-option").forEach((optionButton) => {
              optionButton.classList.toggle("is-selected", optionButton.dataset.value === select.value);
            });
          };

          Array.from(select.options).forEach((option) => {
            const optionButton = document.createElement("button");
            optionButton.type = "button";
            optionButton.className = "custom-select-option";
            optionButton.textContent = option.textContent;
            optionButton.dataset.value = option.value;
            optionButton.setAttribute("role", "option");
            if (!option.value) optionButton.disabled = true;
            optionButton.addEventListener("click", () => {
              if (!option.value) return;
              select.value = option.value;
              select.dispatchEvent(new Event("change", { bubbles: true }));
              close();
            });
            menu.appendChild(optionButton);
          });

          button.addEventListener("click", (event) => {
            event.stopPropagation();
            document.querySelectorAll(".custom-select-wrap.is-open").forEach((openWrapper) => {
              if (openWrapper !== wrapper) {
                openWrapper.classList.remove("is-open");
                const openButton = openWrapper.querySelector(".custom-select");
                if (openButton) openButton.setAttribute("aria-expanded", "false");
              }
            });
            const isOpen = !wrapper.classList.contains("is-open");
            wrapper.classList.toggle("is-open", isOpen);
            button.setAttribute("aria-expanded", isOpen ? "true" : "false");
          });
          select.addEventListener("change", update);
          update();
        }
